# Terraform Module: S3 + RDS + IAM

I'll create a complete Terraform module structure supporting dev/prod environments via tfvars files.

## Directory Structure

```
.
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── s3.tf
│       ├── rds.tf
│       ├── iam.tf
│       ├── variables.tf
│       └── outputs.tf
├── envs/
│   ├── dev/
│   │   ├── main.tf
│   │   ├── backend.tf
│   │   └── terraform.tfvars
│   └── prod/
│       ├── main.tf
│       ├── backend.tf
│       └── terraform.tfvars
└── README.md
```

---

## Module: `modules/app-infra/variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "project" {
  description = "Project/application name, used for naming"
  type        = string
}

variable "region" {
  description = "Primary AWS region"
  type        = string
}

# ----- S3 -----
variable "enable_replication" {
  description = "Enable cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Destination region for CRR"
  type        = string
  default     = "us-west-2"
}

# ----- RDS -----
variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_multi_az" {
  description = "Enable Multi-AZ"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage"
  type        = bool
  default     = true
}

variable "db_allocated_storage" {
  description = "Allocated storage (GB)"
  type        = number
  default     = 20
}

variable "db_backup_retention_days" {
  description = "Backup retention days (>=7 required)"
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days."
  }
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master password (inject via -var-file / SOPS / TF_VAR)"
  type        = string
  sensitive   = true
}

variable "db_subnet_ids" {
  description = "Subnet IDs for DB subnet group (private)"
  type        = list(string)
}

variable "vpc_id" {
  description = "VPC id for security groups"
  type        = string
}

variable "db_ingress_cidrs" {
  description = "CIDRs allowed to reach the DB port"
  type        = list(string)
  default     = []
}

# ----- IAM -----
variable "oidc_provider_arn" {
  description = "OIDC provider ARN for IRSA/service-account trust (prod)"
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "OIDC provider URL (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "K8s namespace for the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "K8s service account name"
  type        = string
  default     = "app-sa"
}

variable "tags" {
  description = "Extra tags"
  type        = map(string)
  default     = {}
}
```

---

## Module: `modules/app-infra/main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.0"
      configuration_aliases = [aws, aws.replica]
    }
  }
}

locals {
  name_prefix = "${var.project}-${var.environment}"
  common_tags = merge(var.tags, {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  })
}

data "aws_caller_identity" "current" {}
```

