## Module: `modules/app-infra/iam.tf`

```hcl
# ---------------------------------------------------------------
# DEV: IAM user with programmatic access (least privilege inline)
# ---------------------------------------------------------------
resource "aws_iam_user" "service" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${local.name_prefix}-svc"
  tags  = local.common_tags
}

resource "aws_iam_access_key" "service" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.service[0].name
}

resource "aws_iam_user_policy" "service" {
  count  = var.environment == "dev" ? 1 : 0
  name   = "${local.name_prefix}-svc-policy"
  user   = aws_iam_user.service[0].name
  policy = data.aws_iam_policy_document.app_access.json
}

# ---------------------------------------------------------------
# PROD: IAM role with OIDC (IRSA) trust — least privilege
# ---------------------------------------------------------------
data "aws_iam_policy_document" "oidc_trust" {
  count = var.environment == "prod" ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "service" {
  count              = var.environment == "prod" ? 1 : 0
  name               = "${local.name_prefix}-svc-role"
  assume_role_policy = data.aws_iam_policy_document.oidc_trust[0].json
  tags               = local.common_tags
}

resource "aws_iam_role_policy" "service" {
  count  = var.environment == "prod" ? 1 : 0
  name   = "${local.name_prefix}-svc-policy"
  role   = aws_iam_role.service[0].id
  policy = data.aws_iam_policy_document.app_access.json
}

# ---------------------------------------------------------------
# Shared least-privilege policy (explicit actions, NO wildcards)
# ---------------------------------------------------------------
data "aws_iam_policy_document" "app_access" {
  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*"
    ]
  }

  statement {
    sid       = "KmsForBucket"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_key.bucket.arn]
  }
}
```

---

## Module: `modules/app-infra/outputs.tf`

```hcl
output "bucket_name" {
  description = "Primary S3 bucket name"
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  description = "Replica bucket name (prod only)"
  value       = var.enable_replication ? aws_s3_bucket.replica[0].id : null
}

output "db_endpoint" {
  description = "RDS endpoint"
  value       = aws_db_instance.this.endpoint
}

output "db_connection_string" {
  description = "Postgres connection string (sensitive)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.this.endpoint}/${var.db_name}"
  sensitive   = true
}

output "service_role_arn" {
  description = "Prod service role ARN"
  value       = var.environment == "prod" ? aws_iam_role.service[0].arn : null
}

output "service_user_name" {
  description = "Dev service user name"
  value       = var.environment == "dev" ? aws_iam_user.service[0].name : null
}

output "service_access_key_id" {
  description = "Dev access key id"
  value       = var.environment == "dev" ? aws_iam_access_key.service[0].id : null
  sensitive   = true
}

output "service_secret_access_key" {
  value     = var.environment == "dev" ? aws_iam_access_key.service[0].secret : null
  sensitive = true
}
```

