## Environment: `envs/dev/main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" {
  region = var.region
}

# Replica provider alias (unused in dev but required by module)
provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

variable "region" { type = string }
variable "vpc_id" { type = string }
variable "db_subnet_ids" { type = list(string) }
variable "db_ingress_cidrs" { type = list(string) }
variable "db_password" {
  type      = string
  sensitive = true
}

module "app_infra" {
  source = "../../modules/app-infra"
  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment              = "dev"
  project                  = "acme-web"
  region                   = var.region
  enable_replication       = false
  db_instance_class        = "db.t3.micro"
  db_multi_az              = false
  db_backup_retention_days = 7
  db_password              = var.db_password
  db_subnet_ids            = var.db_subnet_ids
  vpc_id                   = var.vpc_id
  db_ingress_cidrs         = var.db_ingress_cidrs
}

output "bucket_name" { value = module.app_infra.bucket_name }
output "db_endpoint" { value = module.app_infra.db_endpoint }
```

### `envs/dev/backend.tf`

```hcl
terraform {
  backend "s3" {
    bucket         = "acme-terraform-state"
    key            = "app-infra/dev/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

### `envs/dev/terraform.tfvars`

```hcl
region           = "us-east-1"
vpc_id           = "vpc-0dev11111111"
db_subnet_ids    = ["subnet-0dev1", "subnet-0dev2"]
db_ingress_cidrs = ["10.10.0.0/16"]
# db_password NOT here — see secret handling below
```

