## Environment: `envs/prod/main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

variable "region" { type = string }
variable "replica_region" { type = string }
variable "vpc_id" { type = string }
variable "db_subnet_ids" { type = list(string) }
variable "db_ingress_cidrs" { type = list(string) }
variable "oidc_provider_arn" { type = string }
variable "oidc_provider_url" { type = string }
variable "db_password" {
  type      = string
  sensitive = true
}

module "app_infra" {
  source = "../../modules/app-infra"
  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment              = "prod"
  project                  = "acme-web"
  region                   = var.region
  replica_region           = var.replica_region
  enable_replication       = true
  db_instance_class        = "db.t3.medium"
  db_multi_az              = true
  db_storage_encrypted     = true
  db_backup_retention_days = 14
  db_password              = var.db_password
  db_subnet_ids            = var.db_subnet_ids
  vpc_id                   = var.vpc_id
  db_ingress_cidrs         = var.db_ingress_cidrs

  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  service_account_namespace = "app"
  service_account_name      = "acme-web-sa"
}

output "bucket_name" { value = module.app_infra.bucket_name }
output "replica_bucket_name" { value = module.app_infra.replica_bucket_name }
output "db_endpoint" { value = module.app_infra.db_endpoint }
output "service_role_arn" { value = module.app_infra.service_role_arn }
```

### `envs/prod/backend.tf`

```hcl
terraform {
  backend "s3" {
    bucket         = "acme-terraform-state"
    key            = "app-infra/prod/terraform.tfstate"   # <-- separate key = isolated state
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

### `envs/prod/terraform.tfvars`

```hcl
region            = "us-east-1"
replica_region    = "us-west-2"
vpc_id            = "vpc-0prod2222222"
db_subnet_ids     = ["subnet-0prod1", "subnet-0prod2", "subnet-0prod3"]
db_ingress_cidrs  = ["10.20.0.0/16"]
oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
oidc_provider_url = "oidc.eks.us-east-1.amazonaws.com
